// TODO: o formato exato do payload depende do provedor de WhatsApp escolhido (Meta Cloud API vs BSP).
// Ajustar o parsing abaixo conforme a documentação do provedor real.
const body = $input.item.json.body || {};
const entry = (body.entry && body.entry[0]) || {};
const change = (entry.changes && entry.changes[0] && entry.changes[0].value) || {};
const msg = (change.messages && change.messages[0]) || {};
return {
  json: {
    telefone: msg.from || 'DESCONHECIDO',
    mensagem_recebida: (msg.text && msg.text.body) || '',
    // TODO: cruzar com o lead_id salvo na etapa de outreach (Data Table ou CRM), não está disponível só com o webhook.
    lead_id: null
  }
};

// Extrai o campo {"escalar": ..., "motivo": ...} do fim da resposta da Ana e separa do texto visível ao cliente.
const item = $input.item.json;
const raw = item.output || item.text || '';
const match = raw.match(/\{\s*"escalar"[\s\S]*\}\s*$/);
let escalar = false, motivo = '';
try {
  if (match) {
    const parsed = JSON.parse(match[0]);
    escalar = !!parsed.escalar;
    motivo = parsed.motivo || '';
  }
} catch (e) {}
const textoVisivel = match ? raw.slice(0, match.index).trim() : raw.trim();
return { json: { ...item, resposta_ana: textoVisivel, escalar, motivo_escalonamento: motivo } };

